145: /** Resolve a category to its [main, sub, sub-sub] chain (empty strings for missing levels). */
146: function category_chain($category_id) {
147:     global $conn;
148:     $out = ['', '', ''];
149:     if (!$category_id) return $out;
150:     $ids = [];
151:     $current = (int)$category_id;
152:     while ($current && count($ids) < 3) {
153:         $ids[] = $current;
154:         $stmt = $conn->prepare("SELECT parent_category_id FROM product_categories WHERE category_id = ?");
155:         $stmt->bind_param('i', $current);
156:         $stmt->execute();
157:         $row = $stmt->get_result()->fetch_assoc();
158:         $stmt->close();
159:         if (!$row) break;
160:         $current = $row['parent_category_id'] ? (int)$row['parent_category_id'] : null;
161:     }
162:     $ids = array_reverse($ids);
163:     foreach ($ids as $i => $id) {
164:         $stmt = $conn->prepare("SELECT name FROM product_categories WHERE category_id = ?");
165:         $stmt->bind_param('i', $id);
166:         $stmt->execute();
167:         $row = $stmt->get_result()->fetch_assoc();
168:         $stmt->close();
