174: /** Build a flat list of categories with depth (0 = root, 1 = sub, 2 = sub-sub). */
175: function category_tree($tenant_id) {
176:     $all = fetch_all("SELECT * FROM product_categories WHERE tenant_id = ? ORDER BY name", $tenant_id);
177:     $byParent = [];
178:     foreach ($all as $c) {
179:         $p = $c['parent_category_id'] ? (int)$c['parent_category_id'] : 0;
180:         $byParent[$p][] = $c;
181:     }
182:     $flat = [];
183:     $walk = function ($parent, $depth) use (&$walk, &$byParent, &$flat) {
184:         foreach (($byParent[$parent] ?? []) as $c) {
185:             $flat[] = ['category_id' => (int)$c['category_id'], 'name' => $c['name'], 'depth' => $depth];
186:             $walk((int)$c['category_id'], $depth + 1);
187:         }
188:     };
189:     $walk(0, 0);
190:     return $flat;
191: }

