// A sale must belong to one active store the user is allowed to use.
$stores = accessible_stores(null, false);
if (!$stores) {
    flash_set('danger', 'No active store is assigned to your account. Ask an administrator to grant shop/store access.');
    redirect('index.php');
}
$requested_store_id = (int)($_POST['warehouse_id'] ?? $_SESSION['pos_warehouse_id'] ?? 0);
if ($requested_store_id <= 0) {
    $requested_store_id = (int)$stores[0]['warehouse_id'];
}
$selected_store = find_accessible_store($requested_store_id, false);
if (!$selected_store) {
    $selected_store = $stores[0];
}
$selected_store_id = (int)$selected_store['warehouse_id'];
$_SESSION['pos_warehouse_id'] = $selected_store_id;

// ---- Cart actions ----
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = $_POST['action'] ?? '';

    if ($action === 'set_store') {
        $new_store = find_accessible_store((int)($_POST['warehouse_id'] ?? 0), false);
        if (!$new_store) {
            flash_set('danger', 'That store is not available to your account.');
            redirect('sale-add.php');
        }
        $_SESSION['pos_warehouse_id'] = (int)$new_store['warehouse_id'];
        flash_set('info', 'Selling from ' . store_label($new_store) . '. Cart items were kept; stock is checked again at checkout.');
        redirect('sale-add.php');
    }

    if ($action === 'add_item') {
        $pid = (int)($_POST['product_id'] ?? 0);
        $qty = (float)($_POST['quantity'] ?? 1);
        $product = fetch_one(
            "SELECT p.*, COALESCE((SELECT s.quantity FROM inventory_stock s
                                    WHERE s.product_id = p.product_id AND s.warehouse_id = ? AND s.tenant_id = p.tenant_id), 0) total_stock
             FROM products p WHERE p.product_id = ? AND p.tenant_id = ? AND p.is_active = 1",
            $selected_store_id, $pid, $current_user->tenant_id
        );
        if ($product && $qty > 0) {
            if (!$product['is_service'] && $qty > (float)$product['total_stock']) {
                flash_set('danger', 'Not enough stock for ' . $product['name'] . ' at ' . store_label($selected_store) . ' (available: ' . (float)$product['total_stock'] . ').');
                redirect('sale-add.php');
            }
            $_SESSION['pos_cart'][$pid] = [
                'product_id'    => $pid,
                'code'          => $product['code'],
                'name'          => $product['name'],
                'price'         => (float)$product['sale_price'],
                'tax_rate'      => (float)$product['tax_rate'],
                'quantity'      => $qty,
                'is_service'    => (int)$product['is_service'],
            ];
        }
        redirect('sale-add.php');
    }

    if ($action === 'update_item') {
        $pid = (int)($_POST['product_id'] ?? 0);
        $qty = (float)($_POST['quantity'] ?? 0);
        if (isset($_SESSION['pos_cart'][$pid])) {
            if ($qty <= 0) {
                unset($_SESSION['pos_cart'][$pid]);
            } else {
                $item = $_SESSION['pos_cart'][$pid];
                if (!$item['is_service']) {
                    $product = fetch_one(
                        "SELECT p.*, COALESCE((SELECT s.quantity FROM inventory_stock s
                                                WHERE s.product_id = p.product_id AND s.warehouse_id = ? AND s.tenant_id = p.tenant_id), 0) total_stock
                         FROM products p WHERE p.product_id = ? AND p.tenant_id = ?",
                        $selected_store_id, $pid, $current_user->tenant_id
                    );
                    if (!$product || $qty > (float)$product['total_stock']) {
                        $available = $product ? (float)$product['total_stock'] : 0;
                        flash_set('danger', 'Not enough stock for ' . $item['name'] . ' at ' . store_label($selected_store) . ' (available: ' . $available . ').');
                        redirect('sale-add.php');
                    }
                }
                $item['quantity'] = $qty;
                $_SESSION['pos_cart'][$pid] = $item;
            }
        }
        redirect('sale-add.php');
    }

