432:     $walk = function ($parent, $depth) use (&$walk, &$byParent, &$flat) {
433:         foreach (($byParent[$parent] ?? []) as $c) {
434:             $flat[] = ['category_id' => (int)$c['category_id'], 'name' => $c['name'], 'depth' => $depth];
