content.text:
  font-weight: 500;
  color: #5c6480;
  letter-spacing: 1.4px;
  text-transform: uppercase;
}

.sidebar-menu-title {
  padding: 18px 24px 8px;
  font-size: 10.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1.6px;
  color: #4c5570;
}

.sidebar-menu { list-style: none; margin: 0; padding: 0 14px 24px; }

.sidebar-menu li a {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  margin-bottom: 3px;
  border-radius: 10px;
  color: var(--sidebar-text);
  text-decoration: none;
  font-size: 13.5px;
  font-weight: 500;
}
.sidebar-menu li a i {
  width: 20px;
  text-align: center;
  font-size: 14.5px;
  color: #6d7691;
  transition: color .15s ease;
}
.sidebar-menu li a:hover { background: rgba(255, 255, 255, .05); color: var(--sidebar-text-hover); }
.sidebar-menu li a:hover i { color: #a9a1f0; }
.sidebar-menu li.active a {
  background: rgba(255, 255, 255, .07);
  color: #fff;
  font-weight: 600;
  border: 1px solid rgba(169, 161, 240, .75);
}
.sidebar-menu li.active a i { color: #fff; }

.sidebar-footer {
  margin-top: auto;
  padding: 16px 22px 20px;
  border-top: 1px solid rgba(255, 255, 255, .06);
  font-size: 11px;
  color: #525b75;
}

/* ---------------- App main + topbar ---------------- */
.app-main { margin-left: 258px; min-height: 100vh; display: flex; flex-direction: column; }

.topbar {
  background: rgba(255, 255, 255, .92);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
  height: 64px;
  display: flex;
  align-items: center;
  padding: 0 28px;
  gap: 16px;
  position: fixed;
  top: 0;
  left: 258px;
  right: 0;
  z-index: 900;
}

.topbar-title { font-size: 15.5px; font-weight: 700; }
.topbar-title small {
  display: block;
  font-size: 11px;
  font-weight: 500;
  color: var(--text-muted);
  line-height: 1.2;
}

.topbar-spacer { flex: 1; }

.user-menu {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 6px 10px;
  border-radius: 12px;
  cursor: pointer;
  text-decoration: none;
  color: var(--text);
  transition: background .15s ease;
}
.user-menu:hover { background: var(--bg); text-decoration: none; color: var(--text); }

.avatar {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: #eef0f6;
  color: #4a5468;
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 14px;
  flex-shrink: 0;
}

/* ---------------- Content ---------------- */
.app-content { padding: 28px; margin-top: 64px; flex: 1; }

.page-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 22px;
  flex-wrap: wrap;
  gap: 12px;
}
.page-title { font-size: 21px; font-weight: 800; margin: 0; }
.page-sub { color: var(--text-muted); font-size: 13px; margin-top: 3px; }

/* Sub-page tabs (Users / Roles & Permissions) */
.page-tabs { display: flex; gap: 6px; margin: -6px 0 22px; flex-wrap: wrap; }
.page-tabs .nav-link {
  padding: 8px 18px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
  background: #fff;
  border: 1px solid var(--border);
}
.page-tabs .nav-link:hover { color: var(--primary); border-color: #c8c1f5; }
.page-tabs .nav-link.active { background: var(--primary); border-color: var(--primary); color: #fff; }

/* ---------------- Cards ---------------- */
.card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  margin-bottom: 22px;
}
.card-header {
  background: transparent;
  border-bottom: 1px solid var(--border-soft);
  padding: 16px 22px;
}
.card-title { font-size: 14.5px; font-weight: 700; margin: 0; letter-spacing: .1px; }
.card-body { padding: 22px; }
.card-footer { background: transparent; border-top: 1px solid var(--border-soft); padding: 13px 22px; }

/* ---------------- KPI widgets ---------------- */
.widget {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 20px;
  display: flex;
  align-items: center;
  gap: 16px;
}
.widget-icon {
  font-size: 26px;
  flex-shrink: 0;
  width: 40px;
  text-align: center;
}
.wi-blue { color: #2d7ff9; }
.wi-green { color: #0fb981; }
.wi-amber { color: #e29a0f; }
.wi-red { color: #f0555a; }
.wi-purple { color: #9b59d0; }
.wi-cyan { color: #00b4d8; }
.wi-indigo { color: #6c5ce7; }

.widget-info { min-width: 0; }
.widget-value { font-size: 24px; font-weight: 800; line-height: 1.2; }
.widget-label { color: var(--text-muted); font-size: 12.5px; font-weight: 500; }

/* ---------------- Tables ---------------- */
.table { margin-bottom: 0; }
.table thead th {
  background: #f8f9fd;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .7px;
  border-bottom: 1px solid var(--border);
  padding: 12px 16px;
  white-space: nowrap;
}
.table tbody td {
  padding: 12px 16px;
  border-color: var(--border-soft);
  vertical-align: middle;
  font-size: 13.5px;
}
.table-hover tbody tr { transition: background .1s ease; }
.table-hover tbody tr:hover { background: #f8f9fd; }

/* ---------------- Buttons ---------------- */
.btn { border-radius: 10px; font-weight: 600; font-size: 13.5px; padding: 8px 16px; }
.btn-primary {
  background: var(--primary);
  border-color: var(--primary);
  box-shadow: 0 4px 12px rgba(108, 92, 231, .3);
}
.btn-primary:hover, .btn-primary:focus { background: var(--primary-dark); border-color: var(--primary-dark); }
.btn-outline-primary { color: var(--primary); border-color: #d4cef8; background: #fff; }
.btn-outline-primary:hover { background: var(--primary); border-color: var(--primary); }
.btn-success { background: var(--success); border-color: var(--success); }
.btn-success:hover { background: var(--success-dark); border-color: var(--success-dark); }
.btn-danger { background: var(--danger); border-color: var(--danger); }
.btn-danger:hover { background: #d9434a; border-color: #d9434a; }
.btn-light { background: #f1f3f9; border-color: #e4e7f0; color: var(--text); }
.btn-light:hover { background: #e6e9f3; }
.btn-sm { border-radius: 8px; padding: 5px 11px; font-size: 12.5px; }
.btn-action { padding: 4px 9px; font-size: 12px; border-radius: 8px; margin-right: 4px; }

/* ---------------- Forms ---------------- */
.form-control {
  border-radius: 10px;
  border-color: #dfe3ee;
  font-size: 13.5px;
  padding: 9px 13px;
  height: auto;
  min-height: 40px;
  font-family: inherit;
}
select.form-control, select.form-control:not([size]):not([multiple]) { height: 40px; }
.form-control:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(108, 92, 231, .14);
}
label { font-weight: 600; font-size: 12.5px; color: var(--text); margin-bottom: 6px; }
.input-group-text { border-radius: 10px 0 0 10px; background: #f8f9fd; border-color: #dfe3ee; color: var(--text-muted); }
.input-group .form-control:not(:first-child) { border-radius: 0 10px 10px 0; }
.form-group { margin-bottom: 17px; }

/* ---------------- Badges ---------------- */
.badge { padding: 5px 11px; border-radius: 20px; font-weight: 600; font-size: 11.5px; letter-spacing: .2px; }
.badge-success { background: var(--success-soft); color: #0a8a62; }
.badge-warning { background: var(--warning-soft); color: #b97a09; }
.badge-danger { background: var(--danger-soft); color: #d03b41; }
.badge-info { background: var(--info-soft); color: #1f7fc0; }
.badge-primary { background: var(--primary-soft); color: #5847d8; }
.badge-secondary { background: #f1f3f9; color: #5b6477; }
.badge-purple { background: var(--purple-soft); color: #7d3fae; }

/* ---------------- Alerts ---------------- */
.alert { border-radius: 12px; border: none; font-size: 13.5px; }
.alert-danger { background: var(--danger-soft); color: #c13b41; }

