input.content:
/* ============================================================
   Public storefront
   Kept separate from the staff application styles.
   ============================================================ */

.sf-body {
    background: #f7f7fb;
    color: var(--text, #1c2333);
    min-height: 100vh;
}

.sf-body a { text-decoration: none; }

.sf-container {
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 24px;
}

/* ---------------- Header ---------------- */
.sf-header {
    position: sticky;
    top: 0;
    z-index: 1030;
    background: rgba(255, 255, 255, .97);
    border-bottom: 1px solid #ececf4;
    box-shadow: 0 6px 24px rgba(20, 24, 46, .035);
    backdrop-filter: blur(12px);
}

.sf-header-inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 13px 24px;
    display: flex;
    align-items: center;
    gap: 22px;
}

.sf-brand {
    display: flex;
    align-items: center;
    gap: 11px;
    min-width: 200px;
    color: #1c2333;
    flex: 0 0 auto;
}
.sf-brand:hover { color: #1c2333; }

.sf-brand-logo {
    width: 46px;
    height: 46px;
    object-fit: contain;
    border-radius: 12px;
    background: #fff;
    border: 1px solid #eeeef6;
    padding: 4px;
}

.sf-brand-mark {
    width: 46px;
    height: 46px;
    border-radius: 13px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: #fff;
    font-size: 21px;
    font-weight: 800;
    background: linear-gradient(135deg, #7b61ff, #4a3ac7);
    box-shadow: 0 7px 18px rgba(108, 92, 231, .28);
}

.sf-brand-text { display: flex; flex-direction: column; line-height: 1.18; min-width: 0; }
.sf-brand-text strong {
    font-size: 14.5px;
    font-weight: 800;
    letter-spacing: -.15px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 230px;
}
.sf-brand-text small {
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 1.4px;
    text-transform: uppercase;
    color: #8a90a5;
    margin-top: 3px;
}

.sf-search {
    flex: 1 1 320px;
    max-width: 560px;
    display: flex;
    align-items: center;
    min-width: 180px;
    position: relative;
}
.sf-search input {
    width: 100%;
    height: 43px;
    border: 1px solid #e4e4ef;
    background: #f8f8fc;
    border-radius: 12px;
    padding: 0 46px 0 16px;
    font-size: 13.5px;
    color: #1c2333;
    outline: none;
    transition: border-color .18s ease, box-shadow .18s ease, background .18s ease;
}
.sf-search input::placeholder { color: #98a0b3; }
.sf-search input:focus {
    border-color: #9b8cf3;
    background: #fff;
    box-shadow: 0 0 0 4px rgba(108, 92, 231, .11);
}
.sf-search button {
    position: absolute;
    right: 4px;
    top: 4px;
    width: 35px;
    height: 35px;
    border: 0;
    border-radius: 9px;
    background: transparent;
    color: #6c5ce7;
    cursor: pointer;
}
.sf-search button:hover { background: #f0eeff; }

.sf-actions {
    display: flex;
    align-items: center;
    gap: 9px;
    flex: 0 0 auto;
}

.sf-cart-link {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    height: 42px;
    padding: 0 14px;
    border-radius: 11px;
    border: 1px solid #e7e7f0;
    background: #fff;
    color: #3b4053;
    font-size: 13px;
    font-weight: 700;
    transition: border-color .16s ease, box-shadow .16s ease, transform .16s ease;
}
.sf-cart-link:hover {
    color: #4a3ac7;
    border-color: #c9c1f8;
    box-shadow: 0 5px 14px rgba(74, 58, 199, .09);
    transform: translateY(-1px);
}
.sf-cart-link .fa { font-size: 16px; }
.sf-cart-count {
    min-width: 19px;
    height: 19px;
    padding: 0 5px;
    border-radius: 99px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    background: #6c5ce7;
    color: #fff;
    font-size: 10.5px;
    font-weight: 800;
    line-height: 1;
}

.sf-login-link {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    height: 42px;
    padding: 0 18px;
    border-radius: 11px;
    background: linear-gradient(135deg, #7b61ff, #5a48d9);
    color: #fff;
    font-size: 13px;
    font-weight: 800;
    box-shadow: 0 8px 18px rgba(108, 92, 231, .24);
    transition: transform .16s ease, box-shadow .16s ease;
}
.sf-login-link:hover {
    color: #fff;
    transform: translateY(-1px);
    box-shadow: 0 11px 24px rgba(108, 92, 231, .32);
}
.sf-login-quiet {
    background: transparent;
    color: #7b8194;
    box-shadow: none;
    padding: 0 4px;
    font-weight: 700;
}
.sf-login-quiet:hover { color: #4a3ac7; box-shadow: none; transform: none; }

/* ---------------- Shared elements ---------------- */
.sf-main { min-height: 55vh; }
.sf-page { padding: 42px 24px 74px; }
.sf-muted { color: #7b8194; }
.sf-eyebrow {
    font-size: 10.5px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 1.7px;
    color: #7b61ff;
    display: flex;
    align-items: center;
    gap: 7px;
    margin-bottom: 8px;
}

.sf-flash-wrap { padding-top: 18px; }
.sf-flash { border-radius: 12px; margin: 0; }

.sf-page-head {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    gap: 24px;
    margin-bottom: 28px;
}
.sf-page-head h1 {
    font-size: 33px;
    font-weight: 800;
    letter-spacing: -1.1px;
    margin: 0 0 4px;
    color: #171a28;
}
.sf-page-head p { margin: 0; font-size: 13.5px; }
.sf-text-link { color: #5a48d9; font-size: 13px; font-weight: 700; white-space: nowrap; }
.sf-text-link .fa { margin-right: 4px; }
.sf-text-link:hover { color: #3f2fc4; }

.sf-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    border: 1px solid transparent;
    border-radius: 11px;
    padding: 11px 18px;
    font-size: 13px;
    font-weight: 800;
    line-height: 1.2;
    cursor: pointer;
    transition: transform .16s ease, box-shadow .16s ease, background .16s ease;
}
.sf-btn-primary {
    color: #fff;
    background: linear-gradient(135deg, #7b61ff, #5a48d9);
    box-shadow: 0 9px 20px rgba(108, 92, 231, .25);
}
.sf-btn-primary:hover { color: #fff; transform: translateY(-1px); box-shadow: 0 12px 26px rgba(108, 92, 231, .32); }
.sf-btn-outline { color: #4a3ac7; background: #fff; border-color: #d8d2fa; }
.sf-btn-outline:hover { color: #3f2fc4; background: #f7f5ff; }
.sf-btn-block { width: 100%; }
.sf-btn-small { padding: 8px 11px; font-size: 11.5px; border-radius: 8px; }
.sf-btn-quiet { color: #7b8194; background: #f5f5fa; border-color: #ececf4; }
.sf-btn-quiet:hover { color: #d6454b; background: #fff0f0; border-color: #ffd5d7; }
.sf-btn-add { padding: 9px 12px; font-size: 11.5px; color: #4a3ac7; background: #f2efff; border-color: #e6e1ff; }
.sf-btn-add:hover { color: #fff; background: #6c5ce7; border-color: #6c5ce7; }
.sf-btn-add:disabled { cursor: not-allowed; color: #9aa0b2; background: #f3f3f7; border-color: #ececf2; transform: none; }
.sf-btn:focus-visible, .sf-login-link:focus-visible, .sf-cart-link:focus-visible,
.sf-search button:focus-visible, .sf-filter button:focus-visible {
    outline: 3px solid rgba(108, 92, 231, .28);
    outline-offset: 2px;
}

/* ---------------- Hero ---------------- */
.sf-hero {
    background:
        radial-gradient(circle at 82% 18%, rgba(126, 110, 255, .42), transparent 40%),
        radial-gradient(circle at 18% 82%, rgba(0, 180, 216, .16), transparent 36%),
        linear-gradient(135deg, #141526 0%, #25205a 52%, #4230a5 100%);
    color: #fff;
    overflow: hidden;
    position: relative;
}
.sf-hero::after {
    content: "";
    position: absolute;
    inset: 0;
    opacity: .16;
    background-image: radial-gradient(rgba(255,255,255,.35) 1px, transparent 1px);
    background-size: 22px 22px;
    pointer-events: none;
    mask-image: linear-gradient(90deg, transparent, #000 65%);
}
.sf-hero-inner {
    position: relative;
    z-index: 1;
    display: grid;
    grid-template-columns: minmax(0, 1fr) 330px;
    gap: 48px;
    align-items: center;
    padding-top: 64px;
    padding-bottom: 64px;
}
.sf-hero .sf-eyebrow { color: #c9c1ff; }
.sf-hero h1 {
    font-size: clamp(36px, 5vw, 57px);
    line-height: 1.04;
    letter-spacing: -2.2px;
    font-weight: 800;
    margin: 0 0 18px;
}
.sf-hero-copy > p {
    max-width: 570px;
    color: #cfd0e4;
    font-size: 15px;
    line-height: 1.65;
    margin: 0 0 25px;
}
.sf-hero-points { display: flex; flex-wrap: wrap; gap: 9px; }
.sf-hero-points span {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 8px 12px;
    border: 1px solid rgba(255,255,255,.16);
    background: rgba(255,255,255,.07);
    border-radius: 99px;
    color: #ecebff;
    font-size: 11.5px;
    font-weight: 700;
}
.sf-hero-points .fa { color: #b8adff; }

.sf-hero-card {
    border: 1px solid rgba(255,255,255,.17);
    background: rgba(255,255,255,.08);
    backdrop-filter: blur(8px);
    border-radius: 22px;
    padding: 28px 25px;
    box-shadow: 0 24px 60px rgba(0,0,0,.22);
    display: flex;
    flex-direction: column;
    gap: 8px;
}
.sf-hero-card-icon {
    width: 48px;
    height: 48px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 14px;
    background: rgba(255,255,255,.13);
    color: #d8d2ff;
    font-size: 21px;
    margin-bottom: 9px;
}
.sf-hero-card strong { font-size: 17px; letter-spacing: -.3px; }
.sf-hero-card span { color: #cfd0e4; font-size: 12.5px; line-height: 1.6; }

/* ---------------- Catalogue ---------------- */
.sf-catalogue { padding-top: 54px; padding-bottom: 78px; }
.sf-section-head {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    gap: 25px;
    margin-bottom: 25px;
}
.sf-section-head h2 {
    font-size: 28px;
    line-height: 1.15;
    letter-spacing: -.9px;
    font-weight: 800;
    margin: 0 0 4px;
    color: #171a28;
}
.sf-result-count { margin: 0; font-size: 12.5px; color: #7b8194; }

.sf-filter { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.sf-filter select {
    height: 40px;
    min-width: 170px;
    border: 1px solid #e1e1ec;
    background: #fff;
    border-radius: 10px;
    padding: 0 34px 0 12px;
    font-size: 12.5px;
    color: #3b4053;
    outline: none;
}
.sf-filter select:focus { border-color: #9b8cf3; box-shadow: 0 0 0 4px rgba(108, 92, 231, .1); }
.sf-filter-btn {
    height: 40px;
    border: 1px solid #e1e1ec;
    background: #fff;
    border-radius: 10px;
    padding: 0 13px;
    color: #4a3ac7;
    font-size: 12px;
    font-weight: 800;
    cursor: pointer;
}
.sf-filter-btn:hover { background: #f7f5ff; border-color: #d8d2fa; }
.sf-clear-link { font-size: 12px; font-weight: 700; color: #7b8194; padding: 0 4px; }
.sf-clear-link:hover { color: #d6454b; }

.sf-product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(235px, 1fr));
    gap: 22px;
}
.sf-product-card {
    background: #fff;
    border: 1px solid #ececf4;
    border-radius: 18px;
    overflow: hidden;
    box-shadow: 0 2px 8px rgba(20, 24, 46, .035);
    display: flex;
    flex-direction: column;
    transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
}
.sf-product-card:hover {
    transform: translateY(-3px);
    border-color: #dcd6fb;
    box-shadow: 0 18px 38px rgba(40, 32, 100, .11);
}
.sf-product-media {
    position: relative;
    aspect-ratio: 4 / 3;
    background:
        linear-gradient(135deg, #faf9ff, #f0eeff);
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}
.sf-product-media img { width: 100%; height: 100%; object-fit: cover; display: block; }
.sf-product-placeholder { color: #b9b1ee; font-size: 41px; }
.sf-product-tag {
    position: absolute;
    top: 11px;
    left: 11px;
    padding: 4px 9px;
    border-radius: 99px;
    background: rgba(20, 24, 46, .82);
    color: #fff;
    font-size: 9.5px;
    font-weight: 800;
    letter-spacing: .8px;
    text-transform: uppercase;
}
.sf-product-body { padding: 16px 16px 15px; display: flex; flex-direction: column; flex: 1; }
.sf-product-category {
    color: #7b61ff;
    font-size: 9.5px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 1.15px;
    margin-bottom: 4px;
}
.sf-product-body h3 {
    font-size: 15px;
    line-height: 1.35;
    font-weight: 800;
    letter-spacing: -.25px;
    margin: 0 0 3px;
    color: #1c2333;
}
.sf-product-code { font-size: 10.5px; color: #9aa0b2; letter-spacing: .4px; margin-bottom: 9px; }
.sf-product-desc {
    font-size: 11.5px;
    line-height: 1.55;
    color: #737a8f;
    margin: 0 0 13px;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
    min-height: 35px;
}
.sf-product-desc.sf-muted { font-style: italic; color: #a1a7b7; }
.sf-product-meta { display: flex; align-items: baseline; gap: 5px; margin-top: auto; }
.sf-price { font-size: 16px; font-weight: 800; color: #4a3ac7; letter-spacing: -.3px; }
.sf-unit { font-size: 10.5px; color: #9aa0b2; }
.sf-product-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 9px;
    border-top: 1px solid #f1f1f7;
    margin-top: 13px;
    padding-top: 12px;
}
.sf-stock { font-size: 10.5px; font-weight: 800; display: inline-flex; align-items: center; gap: 4px; white-space: nowrap; }
.sf-stock.in-stock { color: #0b9a6d; }
.sf-stock.out-stock { color: #d6454b; }
.sf-add-form { margin: 0; }

/* ---------------- Empty state ---------------- */
.sf-empty {
    background: #fff;
    border: 1px dashed #ddd9f5;
    border-radius: 20px;
    padding: 60px 24px;
    text-align: center;
    color: #7b8194;
}
.sf-empty > .fa { font-size: 42px; color: #b9b1ee; margin-bottom: 15px; }
.sf-empty h3 { font-size: 20px; font-weight: 800; color: #1c2333; margin: 0 0 5px; }
.sf-empty p { font-size: 13px; margin: 0 0 19px; }

/* ---------------- Cart ---------------- */
.sf-cart-layout, .sf-checkout-layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 340px;
    gap: 28px;
    align-items: start;
}
.sf-cart-list { display: flex; flex-direction: column; gap: 12px; }
.sf-cart-item {
    display: grid;
    grid-template-columns: 82px minmax(0, 1fr) auto auto;
    gap: 15px;
    align-items: center;
    background: #fff;
    border: 1px solid #ececf4;
    border-radius: 15px;
    padding: 14px;
}
.sf-cart-media {
    width: 82px;
    height: 82px;
    border-radius: 11px;
    background: linear-gradient(135deg, #faf9ff, #f0eeff);
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
}
.sf-cart-media img { width: 100%; height: 100%; object-fit: cover; }
.sf-cart-media .sf-product-placeholder { font-size: 29px; }
.sf-cart-info h3 { font-size: 14.5px; font-weight: 800; margin: 0 0 2px; letter-spacing: -.2px; }
.sf-cart-unit { font-size: 11.5px; color: #7b8194; margin-top: 6px; }
.sf-cart-controls { display: flex; align-items: flex-end; gap: 7px; margin: 0; }
.sf-qty-label { display: flex; flex-direction: column; gap: 4px; font-size: 9.5px; font-weight: 800; color: #8a90a5; text-transform: uppercase; letter-spacing: .7px; }
.sf-qty-label input {
    width: 58px;
    height: 35px;
    border: 1px solid #e1e1ec;
    border-radius: 8px;
    text-align: center;
    font-size: 12.5px;
    font-weight: 700;
    color: #1c2333;
    outline: none;
}
.sf-qty-label input:focus { border-color: #9b8cf3; box-shadow: 0 0 0 3px rgba(108, 92, 231, .1); }
.sf-cart-line-total { font-size: 14px; font-weight: 800; color: #1c2333; white-space: nowrap; text-align: right; min-width: 92px; }

.sf-summary {
    background: #fff;
    border: 1px solid #ececf4;
    border-radius: 18px;
    padding: 23px;
    box-shadow: 0 4px 16px rgba(20, 24, 46, .035);
    position: sticky;
    top: 90px;
}
.sf-summary h2 { font-size: 17px; font-weight: 800; letter-spacing: -.3px; margin: 0 0 16px; }
.sf-summary-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 15px;
    padding: 7px 0;
    font-size: 12.5px;
    color: #7b8194;
}
.sf-summary-row strong { font-size: 14px; color: #1c2333; }
.sf-summary-total { border-top: 1px solid #f0f0f6; margin-top: 8px; padding-top: 14px; }
.sf-summary-total strong { font-size: 19px; color: #4a3ac7; }
.sf-summary-note { font-size: 11px; line-height: 1.6; color: #8a90a5; margin: 15px 0 17px; }
.sf-clear-form { margin: 12px 0 0; text-align: center; }
.sf-text-button { border: 0; background: transparent; color: #8a90a5; font-size: 11.5px; font-weight: 700; cursor: pointer; padding: 3px; }
.sf-text-button:hover { color: #d6454b; }
.sf-summary-back { display: inline-block; margin-top: 10px; color: #5a48d9; font-size: 11.5px; font-weight: 800; }
.sf-summary-back:hover { color: #3f2fc4; }

/* ---------------- Checkout ---------------- */
.sf-checkout-card {
    background: #fff;
    border: 1px solid #ececf4;
    border-radius: 18px;
    padding: 28px;
